@module keyDispatch  src=keyDispatch.lua  loc=117  mode=namespace  self=keyDispatch

# Invariants & contracts
  @contract  on fall-through the prefix is NOT finished  @ 14
  @contract  dispatchKeys calls finishPrefix only when a bound command is about to fire  @ 15
  @contract  so idle frames don't kill the buffer  @ 16
  @contract  digit keys count even with Ctrl/Super held, so the chord stays open while typing a count  @ 17
  @contract  Ctrl-N/Super-N command bindings are overridden during prefix mode  @ 18
  @contract  Shift/Alt still disqualify (Shift-digit emits a different char)  @ 19
  @contract  returns early (no dispatch) when state.suppressKbd or not state.acceptCmds  @ 70
  @contract  state.pageSuppressed shrinks the walk to the root keymap only — body-region editors (swing, tuning) suppress page bindings without shadowing globals like playPause/quit  @ 71
  @contract  the walk claims the press before invoking; a command's reads see a queue without it  @ 72
  @contract  first-hit wins; false declines, releases the key and restores its press to the queue  @ 73
  @contract  while cmgr:isPrefixActive(), digits and '/' are captured (no dispatch); Esc cancels; any other key freezes the prefix and falls through to the keychain walk so commands can consumePrefix()  @ 74
  @contract  a captured '/' also opens the menu  @ 75
  @contract  a captured digit dismisses the top scope, resolving the slash as the bar  @ 76
  @contract  while captureLetter is declared, that sink gets bare/Shift letters, not the keychain  @ 77
  @contract  a captured letter comes back in the result, so note entry re-reading the frame skips it  @ 78
  @contract  every claim is at frameMods, as state.claimant -- see docs/keyQueue.md  @ 79

# Shapes
  @shape  dispatchResult = { [imguiKey]=true } — the keys down AND command-bound at the frame's chord  @ 69

# Imports
  @const ImGui = 'imgui'  @ 8

# Module-level constants
  @const keyDispatch = {}  @ 10

# Private functions
  @fn isDigitMods(mods)  @ 20-22
      -- Capture digits and '/' into the prefix buffer; Esc cancels. Returns the entry
      -- it claimed, or nil when no prefix-accumulating key fired this frame.
  @fn handlePrefixCapture(cmgr, keyQueue, claimant)  @ 24-52
  @fn handleLetterCapture(cmgr, keyQueue, claimant)  @ 56-67
      -- A scope may declare a letter sink (the lotus menu's walk); a bare letter goes to it, not
      -- the keychain (Shift tolerated). Returns the key taken, since a leaf may close the sink first.

# Public API (keyDispatch.*)
  @api keyDispatch.dispatchKeys(state, cmgr, keyQueue)  @ 80-115

# Uses (outbound edges)
  @use require imgui  @ <load>:8

# Calls (intra-file)
  @call handleLetterCapture  @ dispatchKeys:83
  @call handlePrefixCapture  @ dispatchKeys:82
  @call isDigitMods  @ handlePrefixCapture:27

# Unresolved receivers
  @drop cmgr:appendPrefix  @ handlePrefixCapture:31,42
  @drop cmgr:cancelPrefix  @ handlePrefixCapture:49
  @drop cmgr:dismissal  @ handlePrefixCapture:34
  @drop cmgr:finishPrefix  @ dispatchKeys:101
  @drop cmgr:invoke  @ handlePrefixCapture:43 dispatchKeys:103
  @drop cmgr:isPrefixActive  @ handlePrefixCapture:25 dispatchKeys:100
  @drop cmgr:keySpec  @ dispatchKeys:91
  @drop cmgr:keychain  @ dispatchKeys:87
  @drop cmgr:letterCapture  @ handleLetterCapture:57
  @drop cmgr:rootKeymap  @ dispatchKeys:87
  @drop keyQueue:frameMods  @ handlePrefixCapture:26 handleLetterCapture:59 dispatchKeys:86
  @drop keyQueue:held  @ dispatchKeys:93
  @drop keyQueue:restore  @ dispatchKeys:105
  @drop keyQueue:take  @ handlePrefixCapture:29,39,47 handleLetterCapture:62 dispatchKeys:96

# REAPER API surface
  @reaper ImGui_GetBuiltinPath
  @reaper MB

# Fields (r read / w write incl. constructor keys)
  @field r ImGui_GetBuiltinPath  @ 4
  @field r Key_0  @ handlePrefixCapture:29
  @field r Key_A  @ handleLetterCapture:62,63
  @field r Key_Escape  @ handlePrefixCapture:47
  @field r Key_Slash  @ handlePrefixCapture:39
  @field r Mod_Ctrl  @ isDigitMods:21
  @field r Mod_Shift  @ handleLetterCapture:60
  @field r Mod_Super  @ isDigitMods:21
  @field r acceptCmds  @ dispatchKeys:81
  @field r claimant  @ dispatchKeys:82,83,96
  @field w dispatchKeys  @ dispatchKeys:80
  @field r pageSuppressed  @ dispatchKeys:87
  @field r path  @ 7
  @field w path  @ 7
  @field r suppressKbd  @ dispatchKeys:81
